{
  "bioavailability_prediction": "low",
  "claims": [
    {
      "card_ids": ["C12"],
      "claim": "The closest high-transfer analogue, bearing the same 4-amidinophenyl group and multiple carboxylates, had absolute oral bioavailability judged not high enough for oral use in humans, directly supporting F < 20% for this zwitterionic peptidomimetic.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C28"],
      "claim": "Perindoprilat, a peptide-like zwitterionic diacid with a cycloalkyl core, had absolute oral bioavailability of 19 ± 7% in young healthy subjects after oral dosing, below the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C13"],
      "claim": "Revefenacin, a large amide/amine drug with multiple ionizable centers, had absolute oral bioavailability <3% in humans, showing that such polar scaffolds can be very poorly absorbed.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C04"],
      "claim": "Emixustat showed low oral bioavailability in healthy subjects, with oral plasma concentrations far below total 14C, supporting poor systemic availability for a molecule with similar polar/amine features.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C24"],
      "claim": "Avanafil had oral bioavailability of only 8–10% in humans, providing another example of a drug with low oral F despite moderate lipophilicity.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C03"],
      "claim": "Tiopronin, a small N-acyl glycine thiol, had absolute oral bioavailability of 63% in healthy subjects, showing that a carboxylate-containing molecule can be well absorbed, but its small size and lack of a basic amidine limit transferability.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C26"],
      "claim": "L-arginine, which shares a guanidine/amidine and carboxylate zwitterion, had oral bioavailability of 68 ± 9% at 6 g in healthy men, but this reflects carrier-mediated amino-acid transport and is dose-dependent, with higher doses falling to ~20%.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C10"],
      "claim": "Sulpiride had absolute oral bioavailability of 27–34% in humans, above threshold, but it lacks the carboxylic acid/amidine zwitterionic motif and its absorption is limited by incomplete GI uptake.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C21"],
      "claim": "5-Methyltetrahydrofolate showed high bioavailability in ileostomy subjects, but this is mediated by dedicated folate transporters and is not applicable to the query's peptidomimetic scaffold.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "high",
  "decision_summary": "The query is a zwitterionic peptidomimetic with a 4-amidinophenyl group and a free carboxylate, structurally aligned with melagatran-like direct thrombin inhibitors. The closest high-transfer analogue (C12) had absolute oral bioavailability too low for oral use, and several other low-F drugs (revefenacin, emixustat, avanafil) support poor systemic absorption. High-F analogues (tiopronin, arginine, sulpiride, folate) depend on small size or specialized transport and do not override the low-F evidence. Prediction: low (<20%).",
  "evidence_gaps": [
    "No direct human absolute oral bioavailability measurement for the query molecule itself; all evidence is from analogues.",
    "The high-F analogues (folate, arginine, tiopronin) rely on specialized transport or small size, so their quantitative F values are not directly transferable.",
    "Fasted-state-specific data are not explicitly reported for most analogues; several records are from healthy subjects without fasting details."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

